    T result;
    istringstream sin(s);
    sin >> result;
    return result;
}

template<class T>
inline T gcd(T a, T b) {
    return (!a) ? b : gcd(b % a, a);
}

template<class T>
inline T mod(T a, T p) {
    a %= p;
    return (a < 0) ? a + p : a;
}

template<class T>
inline int numbits(T n) {
    return (!n) ? 0 : 1 + numbits(n & (n - 1));
