    int *p = new int[end + 1];
    initArray<int>(p, end + 1, 0);
    p[1] = 1;

    for (int i = 2; i <= end; i++) {
        if (!p[i]) {
            if (i >= start)
                vi.push_back(i);

            for (int j = 2 * i; j <= end; j += i)
                p[j] = 1;
        }
    }

    delete[] p;
