bool dfs(int current, int final, int total, int *visited, int **edges, bool flow) {
    if (current == final)
        return true;
    if (visited[current])
        return false;
    visited[current] = true;
    for (int i = 0; i < total; i++)
        if (edges[current][i] && dfs(i, final, total, visited, edges, flow)) {
            if (flow) {
                edges[current][i]--;
                edges[i][current]++;
            }
            return true;
        }
    return false;
}

