    temp_arr[0] = temp_arr[1] = 0;
    for (int i = 2; i <= static_cast<int>(str.size()); i++) {
        temp_arr[i] = -1;
        for (int ind = temp_arr[i - 1]; temp_arr[i] == -1;
             ind = temp_arr[ind]) {
            if (str[ind] == str[i - 1]) {
                temp_arr[i] = ind + 1;
            } else if (ind == 0) {
                temp_arr[i] = 0;
            }
        }
    }
