    int *temp_arr = new int[s2.size() + 1];
    build_failure_function(s2, temp_arr);

    int i = 0;
    int ind = 0;
    while (i < static_cast<int>(s1.size())) {
        if (s1[i] == s2[ind]) {
            res[i] = ++ind;
            if (res[i] == static_cast<int>(s2.size())) {
                ind = temp_arr[ind - 1];
            }
            i++;
        } else if (ind == 0) {
            res[i++] = 0;
        } else {
            ind = temp_arr[ind];
        }
    }

    delete[] temp_arr;
}

